// Daily puzzles + local leaderboard ("board").
//
// Daily puzzles bridge the LIVES OF TWO WELL-KNOWN PEOPLE: an anchor (their
// birth opens the timeline) and an end person (their death closes it, and they
// are preloaded). Both are drawn from the static WELL_KNOWN table
// (src/data/wellknown.js, generated by scripts/fetch-wellknown.mjs), seeded by
// the date, so every day offers three fresh, diverse, verifiably-bridgeable
// pairs — easiest first. Puzzles #2/#3 additionally restrict adds to one
// category (both endpoints belong to it, so the pair itself is on-theme).
//
// Pure logic lives here and is unit-tested (tests/daily.test.mjs). Storage is
// injectable everywhere, so the localStorage board can later be swapped for a
// server-backed one without touching the UI. Players can compare solutions
// across browsers via the standard 🔗 share links (src/features.js).

import { WELL_KNOWN } from "./data/wellknown.js";

export function dateKeyOf(d = new Date()) {
  const p = n => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

function hashStr(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Categories ordered easiest → hardest (denser notable-people data first).
// Puzzle 2 draws from the easier half, puzzle 3 from the harder half.
export const CATEGORY_DIFFICULTY = ["writers", "artists", "women", "scientists", "philosophers", "rulers"];

// Era buckets of the well-known table (computed from birth year).
export function eraOf(birth) {
  if (birth < 500) return "ancient";
  if (birth < 1500) return "medieval";
  if (birth < 1800) return "earlyModern";
  if (birth < 1950) return "modern";
  return "contemporary";
}

// The table normalized to full person objects (living people: death = present).
// Lifespan sanity filter: merged multi-claim rows can produce impossible
// lifespans (>125y), which would fake bridgeability — drop them.
export const MAX_HUMAN_LIFESPAN = 125;
export function wellKnownPool(presentYear) {
  return WELL_KNOWN
    .map(p => ({ ...p, death: p.death ?? presentYear, cats: p.cats || [] }))
    .filter(p => p.death - p.birth >= 0 && p.death - p.birth <= MAX_HUMAN_LIFESPAN);
}

// Minimum number of people needed to cover [s, e] from `sortedCands` (already
// category-filtered, sorted by birth) — greedy interval cover with a single
// sweep, provably optimal for this problem. Returns Infinity when unbridgeable.
function minBridgersSorted(s, e, sortedCands) {
  if (e <= s) return 0;
  let point = s, used = 0, i = 0, reach = s;
  while (point < e) {
    while (i < sortedCands.length && sortedCands[i].birth <= point) {
      if (sortedCands[i].death > reach) reach = sortedCands[i].death;
      i++;
    }
    if (reach <= point) return Infinity;
    point = reach;
    used++;
    if (used > 100) return Infinity;
  }
  return used;
}

// Same, but takes the full pool + optional category mode (filters and sorts).
export function minBridgers(s, e, pool, mode = null) {
  const cands = pool
    .filter(p => (!mode || p.cats.includes(mode)) && p.birth < e && p.death > s)
    .sort((a, b) => a.birth - b.birth);
  return minBridgersSorted(s, e, cands);
}

// ---------------------------------------------------------------- generation
// Three puzzles per day, easiest first. Era bands (by the anchor's birth):
// #1 recent (>= 1800, open category), #2 1000–1799 (easier-half category),
// #3 before 1000 (harder-half category). A pair is accepted only when the two
// lives leave a SUBSTANTIAL gap — the challenge is the stretch between the
// anchor's death and the end's birth (gap must be MIN_GAP..MAX_GAP years) —
// the whole window [anchor.birth, end.death] stays under MAX_SPAN, and the gap
// is bridgeable with at most MAX_BRIDGERS table people of the puzzle's
// category — so every daily is solvable, and with well-known endpoints.

const BANDS = [
  { minBirth: 1750 },               // #1 recent
  { minBirth: 1000, maxBirth: 1750 }, // #2 mid
  { maxBirth: 1000 },               // #3 old
];
const MIN_GAP = 40, MAX_GAP = 160;  // the gap between the two lives, in years
const MAX_SPAN = 400;               // sanity cap on the whole window
const MAX_BRIDGERS = 5;

function shuffled(rng, arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function inBand(p, band) {
  return p.birth >= (band.minBirth ?? -Infinity) && p.birth < (band.maxBirth ?? Infinity);
}

// rawById: id -> raw table entry (so we can tell alive people, death == null,
// apart from the normalized pool where they get death = presentYear).
function pickPair(rng, pool, rawById, band, mode, opts, candsSorted) {
  const { minGap, maxGap, maxSpan, maxBridgers, topN, maxEndsPerAnchor } = opts;
  // anchors must really be dead — their death is where the gap starts
  const anchors = pool.filter(p => {
    const raw = rawById.get(p.id);
    return raw?.death != null && inBand(p, band) && (!mode || p.cats.includes(mode));
  });
  anchors.sort((a, b) => (b.sl ?? 0) - (a.sl ?? 0));
  for (const anchor of shuffled(rng, anchors.slice(0, topN))) {
    const aDeath = rawById.get(anchor.id).death;
    const ends = pool.filter(p => {
      const raw = rawById.get(p.id);
      const gap = raw.birth - aDeath;
      return p.id !== anchor.id &&
        gap >= minGap && gap <= maxGap &&
        (!mode || p.cats.includes(mode)) &&
        p.death - anchor.birth <= maxSpan;
    });
    // the gap between the two lives is the challenge — prefer the BIGGEST gaps
    // (fame breaks ties), then shuffle within the top slice for daily variety
    ends.sort((a, b) => {
      const ga = rawById.get(b.id).birth - aDeath, gb = rawById.get(a.id).birth - aDeath;
      return ga - gb || (b.sl ?? 0) - (a.sl ?? 0);
    });
    for (const end of shuffled(rng, ends.slice(0, maxEndsPerAnchor))) {
      if (minBridgersSorted(aDeath, rawById.get(end.id).birth, candsSorted) <= maxBridgers) {
        return { anchor, end };
      }
    }
  }
  return null;
}

const puzzleCache = new Map(); // dateKey|present -> puzzles (bounded)

export function dailyPuzzles(dateKey, presentYear) {
  const ck = `${dateKey}|${presentYear}`;
  if (puzzleCache.has(ck)) return puzzleCache.get(ck);
  const out = buildDailyPuzzles(dateKey, presentYear);
  if (puzzleCache.size > 60) puzzleCache.clear();
  puzzleCache.set(ck, out);
  return out;
}

function buildDailyPuzzles(dateKey, presentYear) {
  const rng = mulberry32(hashStr(dateKey));
  const pool = wellKnownPool(presentYear);
  const rawById = new Map(WELL_KNOWN.map(p => [p.id, p]));
  const half = Math.floor(CATEGORY_DIFFICULTY.length / 2);
  const cat2 = CATEGORY_DIFFICULTY[Math.floor(rng() * half)];
  const cat3 = CATEGORY_DIFFICULTY[half + Math.floor(rng() * (CATEGORY_DIFFICULTY.length - half))];
  const modes = [null, cat2, cat3];

  // pre-filtered, birth-sorted bridger candidates per category mode (fast sweep)
  const candsByMode = new Map();
  const candsFor = (mode) => {
    if (!candsByMode.has(mode)) {
      candsByMode.set(mode, pool
        .filter(p => !mode || p.cats.includes(mode))
        .sort((a, b) => a.birth - b.birth));
    }
    return candsByMode.get(mode);
  };

  return BANDS.map((band, i) => {
    // strict first, then progressively relaxed so a puzzle is always produced
    const attempts = [
      { minGap: MIN_GAP, maxGap: MAX_GAP, maxSpan: MAX_SPAN, maxBridgers: MAX_BRIDGERS, topN: 40, maxEndsPerAnchor: 12 },
      { minGap: 25, maxGap: 200, maxSpan: 450, maxBridgers: 8, topN: 100, maxEndsPerAnchor: 30 },
      { minGap: 10, maxGap: 260, maxSpan: 500, maxBridgers: 12, topN: 400, maxEndsPerAnchor: 80 },
    ];
    let pair = null;
    for (const opts of attempts) { pair = pickPair(rng, pool, rawById, band, modes[i], opts, candsFor(modes[i])); if (pair) break; }
    if (!pair) {
      // last resort: the largest-gap non-overlapping pair in the band
      // (category-restricted when the puzzle has a mode), preferring pairs
      // whose gap is still bridgeable by table people
      const cands = candsFor(modes[i]);
      let best = null, bestAny = null;
      for (const anchor of pool) {
        const aRaw = rawById.get(anchor.id);
        if (!aRaw?.death || !inBand(anchor, band) || (modes[i] && !anchor.cats.includes(modes[i]))) continue;
        for (const end of pool) {
          const eRaw = rawById.get(end.id);
          const gap = eRaw.birth - aRaw.death;
          if (end.id === anchor.id || gap <= 0) continue;
          if (modes[i] && !end.cats.includes(modes[i])) continue;
          const span = end.death - anchor.birth;
          if (!bestAny || span < bestAny.span) bestAny = { anchor, end, span, gap };
          if (minBridgersSorted(aRaw.death, eRaw.birth, cands) <= 12 && (!best || gap > best.gap)) {
            best = { anchor, end, span, gap };
          }
        }
      }
      pair = (best ?? bestAny) ? { anchor: (best ?? bestAny).anchor, end: (best ?? bestAny).end } : null;
    }
    if (!pair) throw new Error(`well-known table too small to build daily puzzle #${i + 1}`);
    const endYear = pair.end.death ?? presentYear;
    return {
      n: i + 1,
      mode: modes[i],
      anchorId: pair.anchor.id, endId: pair.end.id,
      anchorLabel: pair.anchor.label, endLabel: pair.end.label,
      startYear: pair.anchor.birth, endYear,
      span: endYear - pair.anchor.birth,
    };
  });
}

// Challenge def for starting one daily puzzle from the start screen.
export function dailyDef(dateKey, p) {
  return {
    custom: true,
    key: `daily-${dateKey}-${p.n}`,
    name: `Daily ${dateKey} #${p.n}`,
    mode: p.mode,
    anchorId: p.anchorId,
    endId: p.endId,
    startYear: p.startYear,
    endYear: p.endYear,
    daily: { dateKey, n: p.n },
  };
}

// The next puzzle in today's chain (null after #3).
export function nextDaily(puzzles, n) {
  return puzzles.find(p => p.n === n + 1) ?? null;
}

// ------------------------------------------------------------- leaderboard
// Best-only board: one entry per (dateKey, n) — fewest people wins, ties
// broken by solve time.

const BOARD_KEY = "ttc-daily-board-v1";
const NAME_KEY = "ttc-player-name";

function defaultStorage() {
  try { return typeof localStorage !== "undefined" ? localStorage : null; } catch { return null; }
}

export function loadBoard(storage) {
  const s = storage ?? defaultStorage();
  if (!s) return { entries: [] };
  try {
    const b = JSON.parse(s.getItem(BOARD_KEY) || "{}");
    return { entries: Array.isArray(b.entries) ? b.entries : [] };
  } catch { return { entries: [] }; }
}

// Submit one finished run. Returns { board, improved } — improved=true when
// this run beat the stored best (or there was none).
export function submitResult(board, entry, storage) {
  const e = {
    id: `r${Date.now().toString(36)}-${Math.floor(Math.random() * 1e6).toString(36)}`,
    at: Date.now(),
    name: "Player",
    ...entry,
  };
  const idx = board.entries.findIndex(x => x.dateKey === e.dateKey && x.n === e.n);
  let entries, improved;
  if (idx >= 0) {
    const old = board.entries[idx];
    improved = e.people < old.people || (e.people === old.people && e.ms < old.ms);
    entries = improved ? board.entries.map((x, i) => (i === idx ? e : x)) : board.entries;
  } else {
    entries = [...board.entries, e];
    improved = true;
  }
  const next = { entries };
  const s = storage ?? defaultStorage();
  if (s) { try { s.setItem(BOARD_KEY, JSON.stringify(next)); } catch { /* private mode */ } }
  return { board: next, improved };
}

// Best entry for one daily puzzle (fewest people, then fastest). The store
// upserts, so there is normally at most one; this keeps best-only an invariant
// of the read path too.
export function boardFor(board, dateKey, n) {
  const es = board.entries.filter(e => e.dateKey === dateKey && e.n === n);
  if (!es.length) return [];
  const best = es.reduce((a, b) => (b.people < a.people || (b.people === a.people && b.ms < a.ms) ? b : a));
  return [best];
}

export function bestFor(board, dateKey, n) {
  return boardFor(board, dateKey, n)[0] ?? null;
}

// Player display name for the board; asks once, then persists.
export function playerName(storage) {
  const s = storage ?? defaultStorage();
  if (!s) return "Player";
  let n = null;
  try { n = s.getItem(NAME_KEY); } catch { /* ignore */ }
  if (!n && typeof window !== "undefined" && typeof window.prompt === "function") {
    n = window.prompt("Name for the daily leaderboard?", "Player") || "Player";
    try { s.setItem(NAME_KEY, n); } catch { /* ignore */ }
  }
  return n || "Player";
}

export function fmtMs(ms) {
  const s = Math.max(0, Math.round(ms / 1000));
  return s < 60 ? `${s}s` : `${Math.floor(s / 60)}m ${s % 60}s`;
}
